Np = 1000;
%q = (0:4*Np)/(Np+1);
Emax = 2000;
en = (0:Np)*Emax/(Np+1);
eCut = 500;
peak_pos = 0.4;
%      -,e0,  gamma,A,-, peak_pos
par = [1,eCut,30,   1,0, peak_pos];
%en=eCut*ones(size(q));
q=ones(size(en));
%enAv = sum(en)/numel(en);
wt = test_dsho_fun_w(q,en,par);
Norm = sum(wt)*max(en)/Np %[output:6e5a8080]
%plot(q,wt);
plot(en,wt); %[output:3e50cb3c]
en = eCut*ones(size(q));
q_max = 10;
q  = (0:Np)*q_max/(Np+1);
wt = test_dsho_fun_w(q,en,par); %[output:1aa2e002]
Norm = sum(wt(~isnan(wt)))*max(q)/Np %[output:102a44fb]
plot(q,wt) %[output:7f1b6e6a]
%%

%%
eCut = 500;
peak_pos = 0.1;
%      -,e0,  gamma,A,-, peak_pos
par = [1,eCut,10,   1,0, peak_pos];
q_max=50 %[output:54370251]
q  = (0:Np)*q_max/(Np+1);
en = eCut*ones(size(q));

%wt = test_dsho_fun(q,en,par);
wt = test_dsho_fun_q(q,en,par);
Norm = sum(wt)*q_max/Np; 
[~,midx] = max(wt);disp(Norm);disp(q(midx)) %[output:6603987d]
plot(q,wt) %[output:0fc51820]

